const fs=require("fs"),crypto=require("crypto");
const r=JSON.parse(fs.readFileSync("docs/audit/2026-09-15-completion/advanced.json","utf8"));
const a=JSON.parse(fs.readFileSync("docs/audit/2026-09-15/advanced.json","utf8"));
const sha=p=>crypto.createHash("sha256").update(fs.readFileSync(p)).digest("hex");
const fail=m=>{throw new Error(m)};
if(r.pages.length!==40||a.pages.length!==40)fail("page count");
let counts={fixed:0,"already-fixed":0,open:0},ruChanged=0,enChanged=0,enRead=0,findings=0;
for(let i=0;i<40;i++){
 const p=r.pages[i],old=a.pages[i];
 if(p.path!==old.path||p.findings.length!==old.findings.length)fail("scope "+i);
 if(!p.full_read)fail("full read "+i);
 if(sha(p.path)!==p.after||sha(p.snapshot)!==p.before)fail("SHA "+i);
 if(p.changed_this_pass){ruChanged++;if(p.reread!=="full")fail("reread "+i)}
 for(let j=0;j<p.findings.length;j++){
  const f=p.findings[j]; findings++;counts[f.status]++;
  if(!f.resolution||f.page_sha_before!==p.before||f.page_sha_after!==p.after)fail("finding evidence "+i+"/"+j);
  for(const k of Object.keys(old.findings[j]))if(JSON.stringify(f[k])!==JSON.stringify(old.findings[j][k]))fail("original finding changed "+i+"/"+j+"/"+k);
 }
 if(p.en){enRead++;if(!p.en_full_read||sha(p.en)!==p.en_after)fail("EN "+i);
  const snapshot=".superpowers/sdd/2026-09-15-close-editorial-findings/task-3-before/"+p.en;
  if(sha(snapshot)!==p.en_snapshot_sha256)fail("EN snapshot "+i);
  if(p.en_changed_this_pass){enChanged++;if(p.en_reread!=="full")fail("EN reread "+i)}
 }
}
if(findings!==55||counts.fixed!==48||counts["already-fixed"]!==7||counts.open!==0||ruChanged!==31||enChanged!==4||enRead!==7)fail("final counts");
for(const row of r.validation_results.file_integrity.details)if(sha(row.path)!==row.after||!row.snapshot_matches||!row.figure_reference_order_and_count_preserved&&row.figure_references_unchanged!==true||row.missing_anchors.length)fail("integrity "+row.path);
for(const t of r.validation_results.cpu_checks)if(t.exit_code!==0||!t.executed)fail("test "+t.id);
console.log(JSON.stringify({pages:40,authored_en:enRead,findings,counts,changed_ru:ruChanged,changed_en:enChanged,changed_fully_reread:ruChanged+enChanged,snapshot_and_current_sha_files:47,original_finding_fields:"unchanged",cpu_groups:r.validation_results.cpu_checks.length,result:"PASS"}));
